+/* Dissect a DTM sentence. */
+static int
+dissect_nmea_183_sentence_dtm(tvbuff_t *tvb, packet_info *pinfo _U_, proto_tree *tree)
+{
+    gint offset = 0;
+
+    proto_tree *subtree = proto_tree_add_subtree(tree, tvb, offset,
+                                                 tvb_captured_length(tvb), ett_nmea0183_sentence,
+                                                 NULL, "DTM sentence - Datum Reference");
+
+    offset += dissect_nmea_183_field_datum_code(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_local_datum_code);
+
+    offset += dissect_nmea0183_field(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_local_datum_subdivision_code, NULL);
+
+    offset += dissect_nmea0183_field(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_latitude_offset, "minutes");
+
+    offset += dissect_nmea0183_field(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_latitude_direction, NULL);
+
+    offset += dissect_nmea0183_field(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_longitude_offset, "minutes");
+
+    offset += dissect_nmea0183_field(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_longitude_direction, NULL);
+
+    offset += dissect_nmea0183_field(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_altitude_offset, "metres");
+
+    dissect_nmea_183_field_datum_code(tvb, pinfo, subtree, offset, hf_nmea0183_dtm_reference_datum_code);
+
+    return tvb_captured_length(tvb);
+}
